export const TEXT={"policies.status":{lead:"What the policy is doing now.",items:[["Running","its workers are serving it. The number is how many."],["Starting","a worker is starting up and serves as soon as it is ready."],["Scaled to zero","no worker runs and no GPU is held. The next request starts one and waits while it boots."],["Stopped","by you, or at its monthly budget. It refuses requests until it is started again."],["Building","its new version is being built."],["Crash-looping","its version keeps failing to start, for a reason in the policy itself. Its page says why."],["Failed","its latest version failed to build, or its workers kept failing. Its page says why."],["Ready","built. What it is doing could not be read just now."]]},"policies.workers":"Workers running or starting now, of the most it may run at once, and the card each one holds "+"(1 / 2 · L4). The most is its max GPUs divided by the cards one worker holds. With no max GPUs of its own, only the "+"count shows. A policy on CPU says CPU.","policies.robots":"Robots connected to its workers right now. Robots waiting in line for a slot are not counted.","policies.last":"When one of its workers last answered a request. A dash: none on record.","policies.updated":"When its current version was deployed.","detail.worker-robots":"Robots connected to this worker, of the most it takes at once. For a stopped worker, the most "+"it had connected at once.","detail.tokens":"Robot keys bound to this policy alone. A robot holding one can only connect to it and act, and "+"call the models it declares. Each may have an expiry and a credit limit. Delete one to cut that robot off.","detail.usage-gpu":"GPU time × the cards held: a 2-card worker running an hour is 2 card-h.","detail.usage-cpu":"CPU time × the cores its machines were given.","detail.usage-mem":"Time × the memory its machines were given, in GiB.","detail.usage-network":"What its versions' checks sent saving each image, once a deploy: only what your "+"dependencies did not already hold, at what the machine's cloud charges for it.","eval.n":"The episodes the figure rests on. Episodes that errored are left out.","eval.arm":"One policy, with its settings, that the eval runs. An eval of several has one arm for each.","benchmarks.latest-pass":"The last finished eval's score: the share of its episodes that met the metric this "+"benchmark succeeds by, the one it declares, shown in that metric's unit.","adapters.ran-with":"The benchmark and the policy of the last eval that ran it.","adapters.last":"When an eval last ran it, any version. A dash: none has yet.","adapters.updated":"When its latest version was registered.","billing.added-credit":"Promotion codes, grants and credits you bought, not yet used. Usage comes out of them once "+"this month's free credit is used up. They carry over from month to month.","billing.free-credit":"Free credit your plan gives every month. Usage comes out of it first. It renews at the start "+"of each billing period. What is left does not carry over.","billing.period":"What your usage has cost since this billing period began. It is billed at the end of the period, "+"after this month's credits.","billing.payment-method":"The card each billing period's invoice is charged to, after the period ends. Change it or "+"add another in Payment methods.","usage.builds":"The machine that prepares a version's image, apart from the one its check runs on, and for a "+"benchmark the one that later builds and saves the image its evals load. Each is billed by the second at the CPU "+"and memory rates for builds, checks, evals and benchmarks.","usage.checks":"The machine that loads a version and answers its sample episode before it serves. It is billed by "+"the second from its first second, its boot and the image built on it included: its card at the card's price, "+"its CPU and memory at the rates for builds, checks, evals and benchmarks unless the card's price includes "+"them. A check that fails is billed too.","usage.shells":"The machine a benchmark's shell runs on. It is billed by the second from its first second, as a "+"build check is.","billing.promo":"A code from our team that adds credits to your account, with no payment. Each code works once "+"per account.","adapter.sha256":"This version's fingerprint: its class name and source, hashed. The same file always gets the "+"same one. Every eval records it, so a result names the exact code it ran.","adapter.pairs":"The benchmark → policy pairs this version declares it converts between, each side a name, a "+"template or any, and how many evals ran on each.","bench.replay-version":"Whether an eval of this version records where every object is at each step, so its report "+"can replay each episode in 3D. An eval can turn it off in Run eval.","eval.fastest":"The fastest way to run this eval within your account's GPU limit: how many benchmark machines, "+"the worlds each runs and how many policy machines, from the benchmark's measured step times and the policy's "+"measured times for a batch. Use this sets the two machine fields to it.","eval.machines":"How many benchmark machines play the episodes side by side. More machines finish sooner, each at "+"the same price an hour, and each pays its own start, about 2 minutes.","eval.max-seconds":"How long an episode may run on the robot's clock before it ends unfinished. Empty: each task's "+"own, a standard run. A number applies to every task. Where it is not a task's own, the run is not standard, and "+"its score does not compare with a standard run's.","eval.spend-cap":"The eval stops once it has cost this much. What it ran by then is reported. Empty: no cap.","bench.replay":"Records where every object is at each step, with nothing rendered, so the report can replay each "+"episode in 3D.","bench.io":"What the simulation's first observation holds, as its registration read it: each key with its shape. "+"An adapter turns it into what a policy takes.","bench.defaults":"What an eval of this benchmark runs unless it says otherwise. One eval can change any of them but "+"the machine: on the Run eval page, or with the CLI's flags. An eval of N episodes spreads them over its machines.","bench.default-card":"What each of an eval's machines runs the simulation on: the card this benchmark was registered "+"with, one a machine, or CPU machines for a CPU benchmark.","bench.default-machines":"How many machines an eval starts unless it says more. Each machine runs its own "+"worlds, and the episodes are spread over them, so more machines finish sooner. A machine runs its "+"simulation on one card: an eval grows by machines, not by cards on one machine.","bench.default-worlds":"The most worlds one machine steps at once, as the benchmark declares. An eval builds no more "+"than its episodes and its policy take.","bench.default-seconds":"How long an episode may run on the robot's clock before it ends unfinished. An eval that "+"sets its own is not a standard run, and its success rate does not compare with a standard run's.","step.image":"Building the image on its check machine: the container its machines run, with the packages and system "+"libraries it declares.","step.weights":"Copying the weights: the checkpoint it names, into the storage its workers load it from.","step.upload":"Uploading the code: the files the deploy sends, unpacked for the build.","step.machine":"Opening the machine its check runs on: an available card of its type, started.","step.card":"Waiting for a GPU for its first machine, the card type it runs on, for up to 10 minutes.","step.compile":"Compiling and warming the policy up on its first machine, for each batch size it serves.","step.assets":"Attaching the assets the benchmark declares, which its machines read.","step.load":"Loading the policy and its weights on its check machine.","step.act":"Checking on its check machine: its sample episode played as one robot would, and the build fails if a "+"call of it fails. A policy that marks no sample episode is loaded but not acted on. The machine then stays on as "+"the version's first worker: with no robot acting, it stops after its idle timeout, 60 seconds unless set, "+"counted from when its image is saved, usually a minute or two, billed until then.","step.check":"Checking that it runs: its worlds are built on a machine like the ones its evals use, and each task "+"is reset again and again for a few seconds. It passes when every task resets without hanging and a GPU "+"simulation keeps its card busy. It plays no action: the actions are the benchmark's own.","step.snapshot":"Saving a snapshot of the machine, loaded and warmed. Every later machine of this version starts "+"from it in seconds instead of loading again.","eval.status":{lead:"Where an eval is.",items:[["Queued","the cards it needs are busy. It starts when they are available, or gives up after 10 minutes."],["Pending","accepted, and about to open its machines."],["Starting","its machines are coming up and no episode has begun. Listed under Running."],["Running","its machines are playing the episodes."],["Completed","every episode it could run has run, and it is billed."],["Failed","it stopped on an error, or waited 10 minutes for GPUs and none came. What ran is reported."],["Canceled","stopped by you."]]},"deploy.name":"What this policy is called: on its page here, in seq commands, and in the connect call a robot makes "+'(connect(model="my_pi05_user")). 1 to 64 letters, digits, "_" or "-", starting with a letter or digit. Each '+"of your policies has its own.","key.limit":{lead:"What this key may spend in all. It never resets.",items:[["Counts","the models it calls, the evals it starts, the workers its connects start (their GPU, CPU and "+"memory), and the build checks of what it deploys or registers."],["At the limit","its calls are refused. A deploy, a registration, a connect that would start a worker, or an eval "+"is refused before it starts."],["To go on","raise or remove the limit."]]},"token.limit":{lead:"What this robot key may spend in all. It never resets.",items:[["Counts","the models it calls, and the workers its connects start (their GPU, CPU and memory)."],["Not","a worker another robot key started. A robot that joins one counts toward that key."],["At the limit","it cannot start a worker or call a model. A robot already on a worker keeps its place."],["To go on","raise or remove the limit."]]},"deploy.region":{lead:"Where its workers run.",items:[["Auto","each robot's worker starts in the region nearest the robot, and in another when no card is available "+"there."],["A region","every worker runs in that region alone and waits there for an available card. The regions offered are "+"the ones this policy's card can run in; a deploy that names one it cannot is refused, naming the ones it can."]]},"account.tz":"Used for timestamps in tables, charts and logs.","account.delete":"Deleting this account permanently removes its policies, benchmarks, files, API keys and usage "+"history. Billing records we are required to keep are kept without your name. This action cannot be undone.","account.delete-first":"Settle any balance owed, stop running policies and evaluations, and cancel a paid plan first.","account.delete-keys":"API keys stop working within 5 minutes. Requests using them then fail with 401 Unauthorized.","account.seq-logins":"Each machine where you ran seq login. Sign one out to end its sign-in there; what it holds "+"lapses within the hour.","device.only-you":"Approve only a sign-in you started yourself with seq login. Approving one someone sent you "+"signs their machine in as you.","adapters.what":"An adapter translates between a benchmark and a policy: what one sends, the other reads.","storage.limit":"Everything your account stores counts toward one limit: saved episodes, weights and "+"checkpoints, volume files, eval recordings and the copies its versions keep. Near it the console says so; at it "+"nothing new is stored, and what is stored is kept. Raise it under Storage limit on your Account page, with no cap; "+"left empty, it is your plan's.","keys.full":"Set it as SEQUENCES_API_KEY where the seq CLI runs. It reaches your dev policies; a production policy "+"is managed with a production key.","keys.production":"Set it as SEQUENCES_API_KEY where the seq CLI runs. It reaches your production policies and "+"deploys their new versions; a dev key reaches none of them.","keys.delete":"Requests made with this key will fail with 401 Unauthorized, and a robot connected with it is cut "+"off within about a minute. This action cannot be undone.","detail.robot-key":"One robot's access to this policy and its models.","detail.robot-key-delete":"Requests made with this robot key fail with 401 Unauthorized, and a robot connected "+"with it is cut off at once: its next act is refused. This action cannot be undone.","detail.planner-keys":"One key for each member of this planner: each policy and planner it names, and each device "+"that says things to it. The platform holds its members' keys, made when the planner was deployed; a device's "+"key is shown once. Planner keys have their own ceiling on your plan, apart from robot keys, and the ones the "+"platform holds count toward it.","detail.signing-secret":"Every alert posted to its webhook carries X-Seq-Signature: sha256= and the HMAC-SHA256 of "+"its body with this secret. A receiver that checks it can tell a real alert from a forged one.","detail.planner-key":"For one member of this planner: a policy or a planner it names, whose key the platform holds, "+"or a device that says things to it, which is shown its key once.","detail.planner-key-delete":"The member can no longer use it: this planner no longer reaches a policy or a planner "+"until a key is made for it again, and a device is refused. This action cannot be undone.","detail.promote":"It moves to production and takes one of your plan's production slots. From then on a "+"production key or this console manages it, and a dev key no longer reaches it.","detail.promote-planner":"It moves to production once every policy and planner it names is in production, and takes "+"one of your plan's production slots. From then on a production key or this console manages it.","production.slots":"A policy promoted to production takes one; deleting it frees it.","detail.copy":"A new policy of its own, made from this one: its code, weights and settings are copied and its image "+"built again, the weights stored and billed as its own. Robot keys, kept episodes and versions stay with this one. "+"It starts in dev, and nothing ties the two after."};const plural=(n,one)=>`${n} ${one}${n===1?"":"s"}`;export const SAY={status:(words,stopped,next)=>{if(words==="Stopped")return SAY.stopped(stopped,next);const item=TEXT["policies.status"].items.find((([w])=>w===words));return item?`${item[0]}: ${item[1]}`:null},stopped:(why,next)=>[why==="budget"?"Stopped at its monthly budget. It refuses requests until it is started again.":"Stopped. It refuses requests until it is started again.",SAY.stillBuilding(next)].filter(Boolean).join(" "),stillBuilding:next=>{if(!next)return"";const v=next.version!=null?`v${next.version}`:"";return`${v||"A version"} is still building. It finishes and is checked as usual, its check billed like any worker. `+`Once it passes, ${v||"it"} is the version that serves when you start it.`},workers:({n:n,most:most,cap:cap,cards:cards,card:card,limit:limit})=>{const now=n===null?"Its workers could not be read just now.":`${plural(n,"worker")} running or starting.`;if(!cards)return`${now} It runs on CPU and holds no GPU.`;const each=cards>1?`${cards} ${card} cards`:`one ${card}`;const bound=limit&&cap&&limit<cap?`your account's GPU limit of ${limit} (below its own max GPUs, ${cap})`:`its max GPUs, ${cap},`;return most?`${now} At most ${most} at once: ${bound} over ${plural(cards,"card")} each. Each holds ${each}.`:`${now} No max GPUs of its own, so only your account's GPU limit bounds it. Each holds ${each}.`},ownLimit:(raised,plan,planValue)=>`${raised?"Raised":"Set"} for this account, apart from its plan. `+`The ${plan} plan's own limit: ${planValue===null?"none":planValue}.`,noRequest:"No request on record.",deployWhere:where=>`${where?`${where} `:""}The machine that checks it stays on as its first worker: with no `+"robot acting, it stops after its idle timeout, 60 seconds unless set, counted from when its image is saved, "+"usually a minute or two, billed until then. Then it scales to "+"zero, no worker running and no GPU held, until a robot connects and waits while a worker starts.",step:(phase,state,took,note,built)=>({lead:TEXT[`step.${phase==="act_check"?"act":phase}`]||`The ${phase} step of the build.`,items:state==="bad"?[["Stopped here",note||"the build did not finish"]]:state==="cur"?[["Running",took?`for ${took} so far`:"now"]]:[...took?[["Took",took]]:[],...built?[built]:[]]}),gpuCap:(limit,plan)=>({lead:"The most GPUs this policy may hold at once, counted in cards.",items:[["Robots","max GPUs counts cards, not robots. A worker seats one robot, or several where the policy serves them "+"together. The Workers list on its page shows its seats. A robot past them waits in line."],["Your limit",limit?"what your account may hold at once, its policies and evals together. "+`At most ${limit}${plan?` on the ${plan} plan`:""}. A bigger plan raises it (Billing).`:"at most what your account may hold at once, its policies and evals together (Billing shows it)."],["Later","change it any time without a redeploy, in the policy's Settings."]]}),stopPolicy:({robots:robots=0,workers:workers=0,next:next=null}={})=>{const r=Number(robots)||0;const w=Number(workers)||0;const first=r?`${r===1?"The robot connected to it now is":`The ${r} robots connected to it now are`} `+"disconnected, and no robot can connect until you start it again.":w?`${w===1?"Its worker ends":`Its ${w} workers end`} now, and no robot can connect until you start it again.`:"No robot can connect until you start it again.";const line=r?`Disconnects its ${r===1?"robot":`${r} robots`}.`:w?`Its ${w===1?"worker ends":`${w} workers end`} now.`:"Robots cannot connect until started.";if(!next)return{line:line,tip:first};const v=next.version!=null?`v${next.version}`:"Its new version";return{line:line,tip:`${first} ${v} keeps building, its check billed as usual, and serves when you start it.`}},stopPlanner:({workers:workers=0}={})=>{const w=Number(workers)||0;const ends=w?`${w===1?"Its worker ends":`Its ${w} workers end`} now, and it`:"It";return{line:w?`Its ${w===1?"worker ends":`${w} workers end`} now.`:"It plans nothing until started.",tip:`${ends} plans nothing until you start it again. The policies and planners it names, and their robots, keep `+"running."}},startPlanner:({price:price=null}={})=>price?{line:"It plans again.",facts:[{k:"Each worker",v:price,tip:"Billed while it runs."}]}:{line:"Each worker is billed while running.",tip:"It plans again, and each worker is billed while it runs."},startPolicy:({price:price=null}={})=>price?{line:"Robots can connect again.",facts:[{k:"Each worker",v:price,tip:"Billed while it runs."}]}:{line:"Each worker is billed while running.",tip:"Robots can connect again, and each worker is billed while it runs."},productionSlots:(used,cap)=>`${used} of ${cap} production ${cap===1?"policy":"policies"}`,robotKeys:production=>{const kind=production?"robot production key":"robot develop key";const Kind=kind[0].toUpperCase()+kind.slice(1);return{kind:kind,title:`${Kind}s`,create:`Create ${kind}`,empty:`No ${kind}s yet.`,dialog:`New ${kind}`}},overGpuLimit:(limit,plan)=>({line:`Your account allows ${limit} GPUs.`,tip:`Your account can hold up to ${limit} GPUs at once${plan?` on the ${plan} plan`:""}. Set max GPUs to ${limit} or less.`}),deleteVersion:({version:version,name:name})=>({line:"This cannot be undone.",tip:`v${version} is deleted for good: nothing can bring it back, and what only it holds goes once its workers have `+`ended. ${name} and its other versions stay.`}),deleteBenchVersion:({version:version,name:name})=>({line:"This cannot be undone.",tip:`v${version} is deleted for good: nothing can bring it back, and what only it holds goes once no eval runs it. `+`${name} and its other versions stay.`}),rollback:({to:to,from:from=null,dropping:dropping=null})=>{const said=`v${to} serves from now on, with nothing rebuilt. Robots${from!=null?` on v${from}`:""} move to it at `+`their next episode; when no worker of v${to} is running, one starts first (a cold start).`;return{line:`v${to} serves now, nothing rebuilt.`,tip:dropping!=null?`${said} v${dropping}, still on its way in, is dropped.`:said}},cancelEval:status=>status==="queued"?{line:"It is dropped; nothing billed.",tip:"It is still waiting for GPUs, so it is dropped now and nothing is billed."}:{line:"It stops; billing stops now.",tip:"It starts no new episode and no new machine, and nothing is billed from now on. What ran stays in its report."},copyStorage:({month:month=null,weights:weights="",image:image=""}={})=>month?[{k:"Storage",v:month,sub:[weights&&`${weights} of weights`,image&&`${image} of image`].filter(Boolean).join(" · "),tip:"Stored and billed as its own. Its check is billed by the machine's time, as a deploy's is."}]:null,cancelRegistration:()=>({line:"Its check stops; billed until now.",tip:"Its machines stop now, billed for what they ran until then. Evals run the version before it, if one passed its "+"check."}),redeemed:usd=>`Added ${usd} of credits.`,redeemRefused:({reason:reason=null,retry_after_s:wait=null}={})=>{if(reason==="invalid")return"This code is not valid.";if(reason==="used_up")return"This code has been fully redeemed.";if(reason==="already_redeemed")return"You have already redeemed this code.";if(reason==="too_many_tries")return`Too many tries; wait ${plural(Math.max(1,Math.ceil(Number(wait||0)/60)),"minute")}.`;if(reason==="empty")return"Enter a code.";return"Could not redeem the code."}};